$('#stats').onclick=openStats;$('#nav-stats').onclick=openStats;$('#nav-watchlist').onclick=()=>selectStatus('watchlist');$('#metric-watchlist').onclick=()=>selectStatus('watchlist');$('#metric-favorites').onclick=()=>selectStatus('favorites');$('#export-data').onclick=exportJournal;
$('#hero-save').onclick=()=>{if(selectedId)changeState(selectedId,wanted.has(selectedId)?'none':'watchlist')};$('#hero-random').onclick=()=>{const pool=data.filter(a=>!seen.has(a.id));if(!pool.length){toast('تمام آثار مجموعه را دیده‌ای.');return}const n=new Uint32Array(1);crypto.getRandomValues(n);setAmbient(pool[n[0]%pool.length]);toast('یک انتخاب از میان ندیده‌های تو')};$('#featured-frames').onclick=e=>{if(e.target.closest('[data-carousel-toggle]')){heroPaused=!heroPaused;renderFrames();scheduleHeroRotation();return}const b=e.target.closest('[data-frame]');if(b)setAmbient(data.find(a=>a.id===b.dataset.frame))};
